    "símbolo do infinito": { tone: "craft", category: "Figura", mundane: "O oito deitado; marca do sem-fim.", gloss: "∞ deitado = infinito; 8 em pé = comunicação (Kassia); ver em pé e deitado.", href: "/posts/post-inspecao-expressao-em-pe-e-deitado.html", en: "infinity symbol", es: "símbolo del infinito", fr: "symbole de l'infini", it: "simbolo dell'infinito", de: "Unendlichkeitszeichen", el: "σύμβολο του απείρου", la: "signum infiniti" },
