    "ando, indo, vindo, voltando": { tone: "craft", category: "Ciclo", mundane: "Sequência oral de ir e vir que não desembarca.", gloss: "Expressão — ciclo que não pousa; ando = eu ando; par loop infinito; Valeu !!!", href: "/posts/post-inspecao-expressao-ando-indo-vindo-voltando.html", en: "I walk, going, coming, returning", es: "ando, yendo, viniendo, volviendo", fr: "je marche, allant, venant, revenant", it: "cammino, andando, venendo, tornando", de: "ich gehe, gehend, kommend, zurückkehrend", el: "περπατώ, πηγαίνοντας", la: "ambulo, iens, veniens, rediens" },
